import React, { useState } from 'react';
import { motion, AnimatePresence } from 'motion/react';
import WhiteButton from '../utils/WhiteButton';
import { useCart } from '../context/CartContext';

const ProductCard = ({ image, title, description, price, id, availability, applyPromotions }) => {
  const { addItem } = useCart();
  const [showDescription, setShowDescription] = useState(false);

  const handleAddClick = () => {
    addItem({
      id,
      image,
      title,
      description,
      price,
      availability,
      applyPromotions
    });
  };

  const handleImageClick = () => {
    setShowDescription(!showDescription);
  };

  // Determine availability status - simplified for cleaner design
  const isAvailable = availability > 0;

  return (
    <motion.div 
      className="group relative overflow-hidden h-full"
      initial={{ opacity: 0, y: 20 }}
      animate={{ opacity: 1, y: 0 }}
      transition={{ duration: 0.5, ease: "easeOut" }}
      whileHover={{ y: -2 }}
    >
      {/* Main Card Container - Following Apple's card design philosophy with fixed height */}
      <div className="bg-white/5 backdrop-blur-md rounded-3xl border border-white/10 overflow-hidden transition-all duration-500 hover:bg-white/10 hover:border-white/20 hover:shadow-2xl hover:shadow-white/5 h-full flex flex-col">
        
        {/* Status Indicators - Minimal and purposeful */}
        <div className="absolute top-4 left-4 right-4 flex justify-between items-start z-20 pointer-events-none">
          {/* Promotion Badge - Only when necessary */}
          {applyPromotions === 1 && (
            <motion.div 
              className="bg-gradient-to-r from-purple-500/90 to-indigo-500/90 backdrop-blur-sm px-3 py-1.5 rounded-full"
              initial={{ scale: 0 }}
              animate={{ scale: 1 }}
              transition={{ delay: 0.2 }}
            >
              <span className="text-xs font-medium text-white">Promoción</span>
            </motion.div>
          )}
          
          {/* Availability Indicator - Subtle but informative */}
          <motion.div 
            className={`px-3 py-1.5 rounded-full backdrop-blur-sm transition-all duration-300 ${
              isAvailable 
                ? 'bg-emerald-500/20 border border-emerald-400/30' 
                : 'bg-red-500/20 border border-red-400/30'
            }`}
            initial={{ scale: 0 }}
            animate={{ scale: 1 }}
            transition={{ delay: 0.3 }}
          >
            <span className={`text-xs font-medium ${
              isAvailable ? 'text-emerald-300' : 'text-red-300'
            }`}>
              {isAvailable ? availability : 'Agotado'}
            </span>
          </motion.div>
        </div>

        {/* Hero Image - The star of the show with consistent dimensions */}
        <motion.div 
          className="relative aspect-square cursor-pointer overflow-hidden flex-shrink-0"
          onClick={handleImageClick}
          whileHover={{ scale: 1.02 }}
          whileTap={{ scale: 0.98 }}
          transition={{ duration: 0.2 }}
        >
          {/* Image with elegant hover effect and fallback */}
          <div className="absolute inset-0 bg-gradient-to-b from-transparent via-transparent to-black/20"></div>
          {image ? (
            <img 
              src={image} 
              alt={title} 
              className="w-full h-full object-cover transition-all duration-700 group-hover:scale-105"
            />
          ) : (
            <div className="w-full h-full bg-gradient-to-br from-gray-600/20 to-gray-800/20 flex items-center justify-center">
              <svg className="w-16 h-16 text-white/30" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1} d="M4 16l4.586-4.586a2 2 0 012.828 0L16 16m-2-2l1.586-1.586a2 2 0 012.828 0L20 14m-6-6h.01M6 20h12a2 2 0 002-2V6a2 2 0 00-2-2H6a2 2 0 00-2 2v12a2 2 0 002 2z" />
              </svg>
            </div>
          )}
          
          {/* Subtle click indicator */}
          <div className="absolute inset-0 flex items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity duration-300">
            <motion.div 
              className="bg-white/10 backdrop-blur-sm rounded-full p-3"
              whileHover={{ scale: 1.1 }}
            >
              <svg className="w-6 h-6 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1.5} d="M13 16h-1v-4h-1m1-4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z" />
              </svg>
            </motion.div>
          </div>
        </motion.div>

        {/* Content Section - Clean and purposeful with flex-grow to fill remaining space */}
        <div className="p-4 sm:p-6 space-y-3 sm:space-y-4 flex flex-col flex-grow">
          {/* Title and Price - Primary information with consistent spacing */}
          <div className="space-y-1 sm:space-y-2 flex-shrink-0">
            <h3 className="text-white font-semibold text-base sm:text-lg leading-tight line-clamp-2 group-hover:text-white/90 transition-colors duration-300 min-h-[2.5rem] sm:min-h-[3rem]">
              {title || 'Producto sin título'}
            </h3>
            <div className="text-2xl sm:text-3xl font-bold text-white">
              ${price || '0'}
            </div>
          </div>

          {/* Description - Elegant reveal with consistent spacing */}
          <div className="flex-shrink-0">
            <AnimatePresence>
              {showDescription && (
                <motion.div
                  initial={{ height: 0, opacity: 0 }}
                  animate={{ height: "auto", opacity: 1 }}
                  exit={{ height: 0, opacity: 0 }}
                  transition={{ duration: 0.3, ease: "easeInOut" }}
                  className="overflow-hidden"
                >
                  <motion.p 
                    className="text-white/80 text-xs sm:text-sm leading-relaxed border-t border-white/10 pt-3 sm:pt-4"
                    initial={{ y: -10 }}
                    animate={{ y: 0 }}
                    transition={{ delay: 0.1 }}
                  >
                    {description || 'Sin descripción disponible'}
                  </motion.p>
                </motion.div>
              )}
            </AnimatePresence>
          </div>

          {/* Spacer to push button to bottom */}
          <div className="flex-grow"></div>

          {/* Action Button - Purposeful and clear, always at bottom */}
          <motion.div
            className="flex-shrink-0"
            whileHover={{ scale: 1.02 }}
            whileTap={{ scale: 0.98 }}
          >
            <WhiteButton 
              text={isAvailable ? "Agregar" : "No disponible"}
              onClick={isAvailable ? handleAddClick : undefined}
              className={`w-full py-2.5 sm:py-3 px-4 sm:px-6 text-xs sm:text-sm font-medium rounded-xl sm:rounded-2xl transition-all duration-300 ${
                isAvailable 
                  ? 'hover:shadow-lg hover:shadow-white/10' 
                  : 'opacity-40 cursor-not-allowed'
              }`}
              disabled={!isAvailable}
            />
          </motion.div>
        </div>
      </div>
    </motion.div>
  );
};

export default ProductCard;
